                                <InputGroup label={t('关键帧（中文）', 'Keyframes (CN)')} value={aiShotRowEditor.data?.keyframes_cn || ''} onChange={v => setAiShotRowEditor(prev => ({ ...prev, data: { ...(prev.data || {}), keyframes_cn: v } }))} />
